/// Trusted callbacks handed to protocol packages (OAuth, SAML, SCIM); never HTTP endpoints.
pub struct Federation {
    ctx: Arc<ServerContext>,
    bindings: Arc<crate::api::bindings::BindingsApi>,
}

/// `createFederation(...)`. Construction never fails in the skeleton; validation the TypeScript factory does on
/// construction belongs here when the module is ported.
pub fn create_federation(
    ctx: &Arc<ServerContext>,
    bindings: Arc<crate::api::bindings::BindingsApi>,
) -> IamResult<Federation> {
    Ok(Federation {
        ctx: ctx.clone(),
        bindings,
    })
}

